    S.modelos.forEach(function (mo) {
      if (!mo._agreg) return;
      mo._agreg.partes.forEach(function (p) { malhas++; tri += p.idxCheio.length / 3; });
    });
    return { on: true, malhasMescladas: malhas, triangulos: tri, origem: S._origemAgreg };
