    try { a.memoria = +navigator.deviceMemory || 0; } catch (_) {}
    try { a.toque = !!(window.matchMedia && window.matchMedia('(pointer: coarse)').matches); } catch (_) {}
    try { a.telaMax = Math.max(screen.width || 0, screen.height || 0); } catch (_) {}
