    S.modelos.forEach(function (mo) { mo.grupo.children.forEach(function (m) { if (m.isMesh && m.userData.expressID != null) ms.push((m.userData._matFechada || m.matrix).elements); }); });
    TEXR.ancora = texMotor().ancoraDe(ms);
