    if (typeof Voz !== 'undefined' && (Voz.on || Voz.wanted)) { try { Voz.sair(); } catch (_) {} } // sai da reunião → corta o áudio junto (Voz.wanted cobre o mic em aquisição)
    if (this._connTimer) { clearTimeout(this._connTimer); this._connTimer = 0; }
